        public static let soft = adaptive(light: 0xF5F4F0, dark: 0x2E3029)
        public static let line = adaptive(light: 0xDDDED7, dark: 0x414338)
        public static let onAccent = adaptive(light: 0xFFFFFF, dark: 0x252620)
        public static let status = adaptive(light: 0x667E5A, dark: 0xA3B693)
        public static let danger = adaptive(light: 0xB93248, dark: 0xFF8EA0)
        private static func adaptive(light: UInt32, dark: UInt32) -> Color {
            #if os(macOS)
            return Color(nsColor: NSColor(name: nil) { appearance in
                let value = appearance.bestMatch(from: [.aqua, .darkAqua]) == .darkAqua ? dark : light
                return NSColor(red: CGFloat((value >> 16) & 255) / 255,
                               green: CGFloat((value >> 8) & 255) / 255,
                               blue: CGFloat(value & 255) / 255, alpha: 1)
            })
            #else
            return Color(uiColor: UIColor { traits in
                let value = traits.userInterfaceStyle == .dark ? dark : light
                return UIColor(red: CGFloat((value >> 16) & 255) / 255,
                               green: CGFloat((value >> 8) & 255) / 255,
                               blue: CGFloat(value & 255) / 255, alpha: 1)
            })
            #endif
        }
        #endif
    }
